corrected_code:
const amqp = require('amqplib');

async function initAnalyticsWorker() {
  const conn = await amqp.connect(process.env.RABBITMQ_URL);
  const ch = await conn.createChannel();
  await ch.assertQueue('analytics.export.requests');

  ch.consume('analytics.export.requests', async (msg) => {
    const { tenantId, requestedByUserId, recipientEmail } = JSON.parse(msg.content.toString());

    const userMembership = await pgPool.query(
      'SELECT role FROM tenant_users WHERE tenant_id = $1 AND user_id = $2 AND role IN (\'ADMIN\', \'FINANCE\')',
      [tenantId, requestedByUserId]
    );
    if (userMembership.rowCount === 0) {
      console.error(`Export denied: User ${requestedByUserId} does not have finance role in tenant ${tenantId}`);
      ch.ack(msg);
      return;
    }

    const transactions = await pgPool.query(
      'SELECT * FROM financial_transactions WHERE tenant_id = $1',
      [tenantId]
    );
    const csvData = convertToCsv(transactions.rows);
    await mailer.sendMail({
      to: recipientEmail,
      subject: 'Your financial transactions export',
      attachments: [{ filename: 'transactions.csv', content: csvData }]
    });
    ch.ack(msg);
  });
}
